// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetAdminReadiness Get the redacted operational readiness snapshot (admin).
	// (GET /admin/readiness)
	GetAdminReadiness(ctx context.Context, request GetAdminReadinessRequestObject) (GetAdminReadinessResponseObject, error)
	// Login Log in with username + password.
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Revoke the current session.
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Setup Bootstrap the first admin user (one-shot).
	// (POST /auth/setup)
	Setup(ctx context.Context, request SetupRequestObject) (SetupResponseObject, error)
	// GetAuthStatus Whether setup is needed and whether the caller is authenticated.
	// (GET /auth/status)
	GetAuthStatus(ctx context.Context, request GetAuthStatusRequestObject) (GetAuthStatusResponseObject, error)
	// ListChats List the caller's chats, paginated.
	// (GET /chats)
	ListChats(ctx context.Context, request ListChatsRequestObject) (ListChatsResponseObject, error)
	// CreateChat Create a chat and stream the first assistant turn (SSE).
	// (POST /chats)
	CreateChat(ctx context.Context, request CreateChatRequestObject) (CreateChatResponseObject, error)
	// GetOrCreateEmptyChat Get the caller's reusable "empty chat" (no messages yet), creating one if none exists.
	// (POST /chats/empty)
	GetOrCreateEmptyChat(ctx context.Context, request GetOrCreateEmptyChatRequestObject) (GetOrCreateEmptyChatResponseObject, error)
	// DeleteChat Soft-delete one caller-owned chat.
	// (DELETE /chats/{chatId})
	DeleteChat(ctx context.Context, request DeleteChatRequestObject) (DeleteChatResponseObject, error)
	// GetChat Get a chat's metadata (settings, model, title) — no messages.
	// (GET /chats/{chatId})
	GetChat(ctx context.Context, request GetChatRequestObject) (GetChatResponseObject, error)
	// RenameChat Rename a chat.
	// (PATCH /chats/{chatId})
	RenameChat(ctx context.Context, request RenameChatRequestObject) (RenameChatResponseObject, error)
	// ContinueChat Continue a chat and stream the next assistant turn (SSE).
	// (POST /chats/{chatId})
	ContinueChat(ctx context.Context, request ContinueChatRequestObject) (ContinueChatResponseObject, error)
	// PreviewChatContext Preview the exact context selected for an unsent chat message.
	// (POST /chats/{chatId}/context-preview)
	PreviewChatContext(ctx context.Context, request PreviewChatContextRequestObject) (PreviewChatContextResponseObject, error)
	// ListChatMCPServers List the MCP servers with each one's per-chat enablement + status.
	// (GET /chats/{chatId}/mcp-servers)
	ListChatMCPServers(ctx context.Context, request ListChatMCPServersRequestObject) (ListChatMCPServersResponseObject, error)
	// UpdateChatMCPServer Enable or disable one MCP server for this chat.
	// (PATCH /chats/{chatId}/mcp-servers/{serverId})
	UpdateChatMCPServer(ctx context.Context, request UpdateChatMCPServerRequestObject) (UpdateChatMCPServerResponseObject, error)
	// ListChatMessages List a chat's messages, oldest-first, paginated.
	// (GET /chats/{chatId}/messages)
	ListChatMessages(ctx context.Context, request ListChatMessagesRequestObject) (ListChatMessagesResponseObject, error)
	// UnpinChat Remove a caller-owned chat pin.
	// (DELETE /chats/{chatId}/pin)
	UnpinChat(ctx context.Context, request UnpinChatRequestObject) (UnpinChatResponseObject, error)
	// PinChat Pin one caller-owned chat.
	// (PUT /chats/{chatId}/pin)
	PinChat(ctx context.Context, request PinChatRequestObject) (PinChatResponseObject, error)
	// UpdateChatSettings Update a chat's model-generation settings.
	// (PATCH /chats/{chatId}/settings)
	UpdateChatSettings(ctx context.Context, request UpdateChatSettingsRequestObject) (UpdateChatSettingsResponseObject, error)
	// GetHealth Liveness probe.
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// ImportMCP Import MCP servers from a Claude-style .mcp.json (admin).
	// (POST /mcp/import)
	ImportMCP(ctx context.Context, request ImportMCPRequestObject) (ImportMCPResponseObject, error)
	// ListMCPServers List configured MCP servers (admin).
	// (GET /mcp/servers)
	ListMCPServers(ctx context.Context, request ListMCPServersRequestObject) (ListMCPServersResponseObject, error)
	// CreateMCPServer Add an MCP server (admin).
	// (POST /mcp/servers)
	CreateMCPServer(ctx context.Context, request CreateMCPServerRequestObject) (CreateMCPServerResponseObject, error)
	// DeleteMCPServer Remove an MCP server (admin).
	// (DELETE /mcp/servers/{serverId})
	DeleteMCPServer(ctx context.Context, request DeleteMCPServerRequestObject) (DeleteMCPServerResponseObject, error)
	// UpdateMCPServer Edit an MCP server and reconnect (admin).
	// (PATCH /mcp/servers/{serverId})
	UpdateMCPServer(ctx context.Context, request UpdateMCPServerRequestObject) (UpdateMCPServerResponseObject, error)
	// ReconnectMCPServer Reconnect an MCP server in the background (admin).
	// (POST /mcp/servers/{serverId}/reconnect)
	ReconnectMCPServer(ctx context.Context, request ReconnectMCPServerRequestObject) (ReconnectMCPServerResponseObject, error)
	// ListMCPServerTools List a connected MCP server's tools (admin).
	// (GET /mcp/servers/{serverId}/tools)
	ListMCPServerTools(ctx context.Context, request ListMCPServerToolsRequestObject) (ListMCPServerToolsResponseObject, error)
	// ListModels Merged model list across all configured upstreams.
	// (GET /models)
	ListModels(ctx context.Context, request ListModelsRequestObject) (ListModelsResponseObject, error)
	// ListUpstreamHealth List redacted LLM upstream health snapshots (admin).
	// (GET /upstreams)
	ListUpstreamHealth(ctx context.Context, request ListUpstreamHealthRequestObject) (ListUpstreamHealthResponseObject, error)
	// ListUsers List users (admin).
	// (GET /users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// CreateUser Provision a user (admin).
	// (POST /users)
	CreateUser(ctx context.Context, request CreateUserRequestObject) (CreateUserResponseObject, error)
	// DeleteUser Delete a user (admin).
	// (DELETE /users/{userId})
	DeleteUser(ctx context.Context, request DeleteUserRequestObject) (DeleteUserResponseObject, error)
}

type StrictHandlerFunc func(ctx echo.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares}
}

